{
  "query": "mutation Login($input: LoginDto!) {\n  login(input: $input) {\n    access_token\n    user { id email first_name last_name role }\n  }\n}",
  "variables": {
    "input": {
      "email": "{{userEmail}}",
      "password": "{{password}}"
    }
  }
}

{
  "query": "mutation Register($input: RegisterDto!) {\n  register(input: $input) {\n    access_token\n    user { id email first_name last_name role }\n  }\n}",
  "variables": {
    "input": {
      "email": "{{adminEmail}}",
      "password": "{{password}}",
      "first_name": "Admin",
      "last_name": "Prueba",
      "phone_number": "+573009998877",
      "birth_date": "1995-01-10",
      "sex": "Mujer",
      "weight_kg": 65,
      "height_cm": 168,
      "activity_level": "Activo",
      "goal": "Mantener",
      "diet_type": "Sin_dieta"
    }
  }
}

{
  "query": "mutation ResetPassword($input: ResetPasswordDto!) {\n  resetPassword(input: $input) {\n    access_token\n    user { id email role }\n  }\n}",
  "variables": {
    "input": {
      "token": "{{reset_token}}",
      "newPassword": "{{password}}"
    }
  }
}

{
  "query": "mutation UpdateMe($input: UpdateUserDto!) {
  updateMe(input: $input) { id
email
firstName
lastName
role
phoneNumber
birthDate
sex
weightKg
heightCm
activityLevel
goal
emailNotificationsEnabled
smsNotificationsEnabled }
}",
  "variables": {
    "input": {
      "firstName": "Usuario Editado",
      "smsNotificationsEnabled": false,
      "emailNotificationsEnabled": true
    }
  }
}

{
  "query": "mutation AssignRole($email: String!, $role: String!) {\n  assignRole(email: $email, role: $role) {\n    message\n    user { id email role }\n  }\n}",
  "variables": {
    "email": "{{userEmail}}",
    "role": "nutritionist"
  }
}

{
  "query": "mutation UpdateProduct($id: String!, $input: UpdateProductDto!) {
  updateProduct(id: $id, input: $input) { id
name
category
unit
barcode
brand
description
imageUrl
niCalories
niProtein
niCarbohydrates
niFat
niFiber
niSugars
niSodium
niServingSize }
}",
  "variables": {
    "id": "{{product_id}}",
    "input": {
      "description": "Producto actualizado desde Postman"
    }
  }
}

{
  "query": "mutation CreateInventoryItem($input: CreateInventoryItemDto!) {
  createInventoryItem(input: $input) { id
productName
quantity
unit
category
location
barcode
notes
expirationDate
purchaseDate
alertSent
product {
  id
  name
}
user {
  id
  email
} }
}",
  "variables": {
    "input": {
      "productId": "{{product_id}}",
      "productName": "Manzana Roja",
      "category": "fruits",
      "quantity": 2,
      "unit": "kg",
      "purchaseDate": "{{today}}",
      "expirationDate": "{{futureDate}}",
      "location": "Cocina",
      "notes": "Creado desde Postman GraphQL"
    }
  }
}

{
  "query": "query InventoryItems($filter: InventoryFilter, $userId: String) {
  inventoryItems(filter: $filter, userId: $userId) { id
productName
quantity
unit
category
location
barcode
notes
expirationDate
purchaseDate
alertSent
product {
  id
  name
}
user {
  id
  email
} }
}",
  "variables": {
    "filter": {
      "q": "manzana",
      "category": "fruits"
    },
    "userId": null
  }
}

{
  "query": "query InventoryStats($userId: String) {
  inventoryStats(userId: $userId) {
    totalItems
    expiringSoon
    expired
  }
}",
  "variables": {
    "userId": null
  }
}

{
  "query": "query InventoryItem($id: String!) {
  inventoryItem(id: $id) { id
productName
quantity
unit
category
location
barcode
notes
expirationDate
purchaseDate
alertSent
product {
  id
  name
}
user {
  id
  email
} }
}",
  "variables": {
    "id": "{{inventory_item_id}}"
  }
}

{
  "query": "mutation UpdateInventoryItem($id: String!, $input: UpdateInventoryItemDto!) {
  updateInventoryItem(id: $id, input: $input) { id
productName
quantity
unit
category
location
barcode
notes
expirationDate
purchaseDate
alertSent
