} }
}",
  "variables": {
    "id": "{{inventory_item_id}}",
    "input": {
      "quantity": 3,
      "location": "Nevera"
    }
  }
}

{
  "query": "mutation ConsumeInventoryItems($input: ConsumeInventoryItemsDto!) {
  consumeInventoryItems(input: $input) {
    updated { id
productName
quantity
unit
category
location
barcode
notes
expirationDate
purchaseDate
alertSent
product {
  id
  name
}
user {
  id
  email
} }
    removed { id
productName
quantity
unit
category
location
barcode
notes
expirationDate
purchaseDate
alertSent
product {
  id
  name
}
user {
  id
  email
} }
  }
}",
  "variables": {
    "input": {
      "items": [
        {
          "id": "{{inventory_item_id}}",
          "quantity": 1
        }
      ]
    }
  }
}

{
  "query": "mutation DeleteInventoryItem($id: String!) {
